item.content:encoded:
.card-container {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.card {
  border: 1px solid #ddd;
  padding: 10px;
  border-radius: 5px;
  text-align: center;
  width: calc(33.333% - 20px);
  box-sizing: border-box;
}
.copy-btn {
  margin-top: 10px;
  padding: 5px 10px;
  cursor: pointer;
}
